static inline uint32_t emergencyCnNextCodepoint(const char *&text) {
  const uint8_t first = uint8_t(*text++);
  if (first < 0x80) return first;
  uint32_t cp = first & (first < 0xE0 ? 0x1F : 0x0F);
  const int extra = first < 0xE0 ? 1 : 2;
  for (int i = 0; i < extra; ++i) {
    if (!*text) return 0;
    cp = (cp << 6) | (uint8_t(*text++) & 0x3F);
  }
  return cp;
}
static inline void drawEmergencyCnText(const char *text, int cx, int y, uint16_t color) {
  int count = 0;
  const char *at = text;
  while (*at) { emergencyCnNextCodepoint(at); ++count; }
  int x = cx - count * 24 / 2;
  while (*text) {
    const uint32_t cp = emergencyCnNextCodepoint(text);
    for (size_t g = 0; g < sizeof(EMERGENCY_CN_CODEPOINTS) / sizeof(EMERGENCY_CN_CODEPOINTS[0]); ++g) {
      if (EMERGENCY_CN_CODEPOINTS[g] != cp) continue;
      for (int yy = 0; yy < 24; ++yy) {
        for (int xx = 0; xx < 24; ++xx) {
          if (pgm_read_byte(&EMERGENCY_CN_BITMAPS[g][yy * 3 + xx / 8]) & (0x80 >> (xx % 8)))
            gfx->drawPixel(x + xx, y + yy, color);
        }
      }
      break;
    }
    x += 24;
  }
}
